146												</div>
147												<div data-testid="ac-when-full">
148													<span class="font-medium text-muted-foreground">When:</span>
149													{ac.when}
150												</div>
151												<div data-testid="ac-then-full">
152													<span class="font-medium text-muted-foreground">Then:</span>
153													{ac.then}
154												</div>
155												<!-- AC: @web-dashboard ac-15 - Test coverage indicator -->
156												<div
157													data-testid="test-coverage-indicator"
158													class="text-xs mt-2 inline-flex items-center gap-1 {ac.covered === true
159														? 'text-green-600 covered'
160														: ac.covered === false
161															? 'text-amber-600 uncovered'
162															: 'text-muted-foreground unknown'}"
163												>
164													{#if ac.covered === true}
165														<CheckCircle class="w-3 h-3" />
166														<span>Covered</span>
167													{:else if ac.covered === false}
168														<XCircle class="w-3 h-3" />
169														<span>Not covered</span>
170													{:else}
171														<HelpCircle class="w-3 h-3" />
172														<span>Coverage: Unknown</span>
173													{/if}
174												</div>
175											</div>
176										</AccordionContent>
177									</AccordionItem>
178								{/each}
179							</Accordion>
180						</div>
