189									<Button
190										variant="outline"
191										size="sm"
192										data-testid="trait-chip"
193										onclick={() => {
194											// AC: @web-dashboard ac-14 - Navigate to trait detail
195											// Traits are items (type: trait), so we navigate to items view with the ref
196											const traitRef = trait.startsWith('@') ? trait.slice(1) : trait;
197											goto(`${base}/items?ref=${encodeURIComponent(traitRef)}`);
198										}}
199									>
200										<span data-testid="trait-title">{trait}</span>
201									</Button>
202								{/each}
203							</div>
204						</div>
205					{/if}
206	
