  1	<script lang="ts">
  2		// AC: @web-dashboard ac-11, ac-12, ac-13, ac-14, ac-15
  3		// AC: @multi-directory-daemon ac-27 - Reload on project change
  4		import { onMount } from 'svelte';
  5		import { page } from '$app/stores';
  6		import type { ItemSummary } from '@kynetic-ai/shared';
  7		import { fetchItems } from '$lib/api';
  8		import ItemTree from '$lib/components/ItemTree.svelte';
  9		import ItemDetail from '$lib/components/ItemDetail.svelte';
 10		import { Skeleton } from '$lib/components/ui/skeleton';
 11		import { getProjectVersion } from '$lib/stores/project.svelte';
 12	
 13		let items = $state<ItemSummary[]>([]);
 14		let loading = $state(true);
 15		let error = $state<string | null>(null);
 16		let selectedRef = $state<string | null>(null);
 17		let detailOpen = $state(false);
 18	
 19		async function loadItems() {
 20			loading = true;
 21			error = null;
 22			try {
 23				const response = await fetchItems();
 24				items = response.items;
 25			} catch (err) {
 26				error = err instanceof Error ? err.message : 'Failed to load spec items';
 27				items = [];
 28			} finally {
 29				loading = false;
 30			}
 31		}
 32	
 33		function handleSelect(event: CustomEvent<string>) {
 34			selectedRef = event.detail;
 35			detailOpen = true;
 36	
 37			// Update URL
 38			const url = new URL(window.location.href);
 39			url.searchParams.set('ref', event.detail);
 40			window.history.pushState({}, '', url);
 41		}
 42	
 43	
 44		// Clear URL param when detail panel closes via bind:open
 45		$effect(() => {
 46			if (!detailOpen && selectedRef) {
 47				selectedRef = null;
 48				const url = new URL(window.location.href);
 49				url.searchParams.delete('ref');
 50				window.history.pushState({}, '', url);
 51			}
 52		});
 53	
 54		// React to URL ref param changes (handles both initial load and navigation)
 55		$effect(() => {
 56			const urlRef = $page.url.searchParams.get('ref');
 57			if (urlRef && urlRef !== selectedRef) {
 58				selectedRef = urlRef;
 59				detailOpen = true;
 60			}
 61		});
 62	
 63		onMount(() => {
 64			loadItems();
 65		});
 66	
 67		// AC: @multi-directory-daemon ac-27 - Reload data when project changes
 68		$effect(() => {
 69			const version = getProjectVersion();
 70			if (version > 0) {
 71				loadItems();
 72			}
 73		});
 74	</script>
 75	
 76	<div class="flex flex-col gap-4">
 77		<div class="flex items-center justify-between">
 78			<h1 class="text-3xl font-bold">Spec Items</h1>
 79			<p class="text-sm text-muted-foreground">{items.length} items total</p>
 80		</div>
 81	
 82		{#if loading}
 83			<div class="space-y-4">
 84				<Skeleton class="h-12 w-full" />
 85				<Skeleton class="h-12 w-full" />
 86				<Skeleton class="h-12 w-full" />
 87				<Skeleton class="h-12 w-full" />
 88			</div>
 89		{:else if error}
 90			<div
 91				class="rounded-md border border-destructive bg-destructive/10 p-4"
 92				data-testid="error-message"
 93				role="alert"
 94			>
 95				<p class="text-destructive font-medium">Error loading spec items</p>
 96				<p class="text-sm text-destructive/80">{error}</p>
 97			</div>
 98		{:else}
 99			<ItemTree {items} on:select={handleSelect} />
100		{/if}
101	</div>
102	
103	<ItemDetail ref={selectedRef} bind:open={detailOpen} />

