  7	
  8	/**
  9	 * Common paginated response wrapper
 10	 * AC: @api-contract ac-4
 11	 */
 12	export interface PaginatedResponse<T> {
 13	  items: T[];
 14	  total: number;
 15	  offset: number;
 16	  limit: number;
 17	}
 18	
 19	/**
 20	 * Standard error response
 21	 * AC: @api-contract ac-22, ac-23, ac-24
 22	 */
 23	export interface ErrorResponse {
 24	  error: string;
 25	  message?: string;
 26	  suggestion?: string;
 27	  details?: Array<{ field: string; message: string }>;
 28	  current?: string;
 29	  valid_transitions?: string[];
 30	}
