 39	  title: string;
 40	  type: string;
 41	  status: string;
 42	  priority: number;
 43	  spec_ref?: string;
 44	  tags: string[];
 45	  depends_on: string[];
 46	  automation?: string;
 47	  created_at: string;
 48	  started_at?: string;
 49	  notes_count: number;
 50	  todos_count?: number;
 51	}
